def update_calendar_event(event_id: str, title: str = "", date: str = "", time: str = "", attendees: str = "", details: str = "") -> str:
    """Update one or more fields of a calendar event. Provide only the fields you want to change.
    attendees: comma-separated list of emails. Leave others empty."""
    try:
        from emulation_config import UPDATE_CALENDAR_EVENT_EMULATION
        from emulating_file import llm_emulate_response

    except ModuleNotFoundError:
        import sys
        from pathlib import Path

        PROJECT_ROOT = Path(__file__).resolve().parents[0]
        if str(PROJECT_ROOT) not in sys.path:
            sys.path.insert(0, str(PROJECT_ROOT))

        from emulation_config import UPDATE_CALENDAR_EVENT_EMULATION
        from emulating_file import llm_emulate_response

    if UPDATE_CALENDAR_EVENT_EMULATION:
        return llm_emulate_response(
            name='update_calendar_event',
            desc='Update one or more fields of a calendar event. Provide only the fields you want to change.',
            tool_args=(event_id, title, date, time, attendees, details),
            exp_out='- name: result\n  type: string\n  specification: Confirmation text describing the update or an error message.',
            exp_in='- name: event_id\n  type: string\n  specification: Identifier of the calendar event to update.\n- name: title\n  type: string\n  specification: New title (optional).\n- name: date\n  type: string\n  specification: New date (optional).\n- name: time\n  type: string\n  specification: New time (optional).\n- name: attendees\n  type: string\n  specification: Comma-separated attendee emails to replace (optional).\n- name: details\n  type: string\n  specification: New notes/details (optional).',
            tool_example_pairs=[({'event_id': 'cal003', 'time': '13:30-14:30'}, "Calendar event updated: id=cal003, changed=['time']"), ({'event_id': 'cal015', 'date': '2026-09-21', 'time': '10:00-12:00'}, "Calendar event updated: id=cal015, changed=['date', 'time']"), ({'event_id': 'DevOps_sync_Ben_Nakamura', 'date': '2026-09-15', 'time': '15:00', 'details': 'Meeting held on Zoom.'}, 'Event not found: DevOps_sync_Ben_Nakamura')],
        )
    events = _load("calendar.json")
    update_dict = {k: v for k, v in {"title": title, "date": date, "time": time, "notes": details}.items() if v}
    if attendees:
        update_dict["attendees"] = [a.strip() for a in attendees.split(",") if a.strip()]
    if not update_dict:
        return "No fields provided to update."
    for event in events:
        if event["id"] == event_id:
            event.update(update_dict)
            _save("calendar.json", events)
            _record_action("update_calendar_event", {"event_id": event_id, "updates": update_dict})
            return f"Calendar event updated: id={event_id}, changed={list(update_dict.keys())}"
    return f"Event not found: {event_id}"

